-- Biology Ch12: Genetics and Evolution — BATCH 3 (Mutations + Hardy-Weinberg + Population Genetics)
-- Safe to re-run: deletes only this batch's subtopics, then re-inserts.

DELETE FROM questions WHERE topic = 'Genetics and Evolution' AND subtopic IN ('Mutations', 'Hardy-Weinberg Equilibrium', 'Genetic Drift & Population Change');

-- Q1 [Mutations] easy skill2 ans=A
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES ('bio_biochem', 'Genetics and Evolution', 'Mutations', 'A geneticist sequencing the human β-globin gene in a healthy individual finds a single-base substitution at the third nucleotide of one codon, yet the codon still specifies the same amino acid as the reference sequence. Which outcome is this substitution most likely to have on the encoded β-globin protein?', '[{"label": "A", "text": "No change in the amino acid sequence"}, {"label": "B", "text": "Replacement of one amino acid by another"}, {"label": "C", "text": "Early termination of the protein"}, {"label": "D", "text": "A shifted translational reading frame"}]'::jsonb, 'A', 'This is a Biology question that falls under the content category ''Transmission of Heritable Information from Generation to Generation.'' The answer is A because a single-base substitution in the third base of a codon that still specifies the same amino acid is a silent mutation, which the textbook describes as a point mutation that is "not detectable in the final product." OpenStax states that "Silent mutations are usually due to a substitution in the third base of a codon, which often represents the same amino acid as the original codon," so the β-globin protein''s amino acid sequence is unchanged. This redundancy reflects the degeneracy of the genetic code, in which "codons that specify the same amino acid typically only differ by one nucleotide." (Choice A) is correct: because the substituted codon encodes the same amino acid, the protein sequence is not altered and the mutation is silent. (Choice B) describes a different point-mutation outcome — "Other point mutations can result in the replacement of one amino acid by another, which may alter the function of the protein" — but that requires the codon to specify a new amino acid, which is not the case here. (Choice C) describes a nonsense outcome, since "Point mutations that generate a stop codon can terminate a protein early," but a silent substitution does not create a stop codon. (Choice D) describes a frameshift, which arises only from an insertion or deletion that alters the reading frame, not from a single-base substitution. This is a Scientific Reasoning and Problem Solving question because you must apply the definition of a silent mutation and the degeneracy of the genetic code to predict the protein-level consequence of a specific third-base substitution.', 'easy', '1C', 'Transmission of Heritable Information from Generation to Generation', 'biology', 2, 75)
  RETURNING id
)
