  SELECT id, 'B', 'adjacent_fact', NULL FROM q
  UNION ALL
  SELECT id, 'C', 'adjacent_fact', NULL FROM q
  UNION ALL
  SELECT id, 'D', 'process_step_confusion', NULL FROM q;

-- Q2 [Mutations] medium skill2 ans=B
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES ('bio_biochem', 'Genetics and Evolution', 'Mutations', 'A child with beta-thalassemia carries a hemoglobin allele in which a single base substitution changes the codon CAG (glutamine) to UAG within the coding region, so the ribosome releases a truncated beta-globin chain. This single-base change is best classified as which type of mutation?', '[{"label": "A", "text": "Silent mutation"}, {"label": "B", "text": "Nonsense mutation"}, {"label": "C", "text": "Frameshift mutation"}, {"label": "D", "text": "Chromosomal translocation"}]'::jsonb, 'B', 'This is a Biology question that falls under the content category ''Transmission of Heritable Information from Generation to Generation.'' The answer is B because the substitution converts a codon that specified an amino acid (CAG, glutamine) into UAG, one of the three stop codons, so translation halts and a shortened protein is released. OpenStax states that "Point mutations that generate a stop codon can terminate a protein early" (openstax-biology-2e.txt, lines 17487-17488), and that the nonsense codons UAA, UAG, and UGA "terminate protein synthesis and release the polypeptide from the translation machinery" (lines 17929-17930). Because only one base pair is altered, this is a point mutation, and the specific outcome of a premature stop codon defines it as a nonsense mutation. (Choice A) Silent mutations are "usually due to a substitution in the third base of a codon, which often represents the same amino acid as the original codon" and are "not detectable in the final product" (lines 17484-17486); here the protein is clearly altered (truncated), so it is not silent. (Choice B) is correct: a point mutation that generates a stop codon terminates the protein early, matching the CAG-to-UAG change that releases a truncated chain (lines 17487-17488). (Choice C) A frameshift requires an insertion or deletion that alters "the translational reading frame," and "the resultant protein is usually nonfunctional" (lines 17492-17494); a single base substitution does not shift the reading frame, so this is not a frameshift. (Choice D) A translocation occurs when "a piece of DNA from one chromosome may get translocated to another chromosome or to another region of the same chromosome" (lines 17494-17496); a single base substitution within one codon is not a chromosome-level rearrangement. This is a Scientific Reasoning and Problem Solving question because you must apply the definitions of mutation types to a specific codon change to infer the mechanism that produced the truncated protein.', 'medium', '1C', 'Transmission of Heritable Information from Generation to Generation', 'biology', 2, 105)
  RETURNING id
)
