-- Q3 [Mutations] hard skill2 ans=C
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES ('bio_biochem', 'Genetics and Evolution', 'Mutations', 'A researcher studying a human disease gene compares two mutant alleles: allele 1 carries a single-nucleotide insertion early in the coding sequence, and allele 2 carries a three-nucleotide insertion at the same position. Allele 1 produces a nonfunctional protein, whereas allele 2 produces a nearly full-length, partially functional protein. Which mechanism best accounts for why the single-nucleotide insertion is the more deleterious of the two?', '[{"label": "A", "text": "It substitutes one amino acid for another"}, {"label": "B", "text": "It silently alters a third-base codon position"}, {"label": "C", "text": "It shifts the reading frame for every downstream codon"}, {"label": "D", "text": "It translocates the gene to another chromosome"}]'::jsonb, 'C', 'This is a Biology question that falls under the content category ''Transmission of Heritable Information from Generation to Generation.'' The answer is C because a single-nucleotide insertion alters the translational reading frame, so that every codon downstream of the insertion is misread, and the resulting protein is usually nonfunctional. OpenStax states that "If an insertion or deletion results in the alteration of the translational reading frame (a frameshift mutation), the resultant protein is usually nonfunctional" (Biology 2e, lines 17492-17493). By contrast, an insertion of three nucleotides preserves the reading frame: "Though insertion of three nucleotides caused an extra amino acid to be inserted during translation, the integrity of the rest of the protein was maintained" (lines 17916-17917), which is why "A frameshift mutation that results in the insertion of three nucleotides is often less deleterious than a mutation that results in the insertion of one nucleotide" (lines 17514-17515). The insertion of one or two nucleotides "completely changed the triplet reading frame, thereby altering the message for every subsequent amino acid" (lines 17914-17915). (Choice A) is incorrect: substituting one amino acid for another describes a point-mutation substitution, not an insertion, and a single substitution typically affects only one residue rather than the entire downstream sequence (lines 17486-17487). (Choice B) is incorrect: a silent third-base substitution often specifies the same amino acid and is "not detectable in the final product," so it would make the protein less deleterious, not more (lines 17484-17486). (Choice C) is correct: shifting the reading frame causes every subsequent codon to be misread, usually yielding a nonfunctional protein, while keeping the frame intact (the +3 insertion) preserves the rest of the protein (lines 17492-17493, 17914-17917). (Choice D) is incorrect: relocation of DNA to another chromosome describes translocation, a distinct mutation type, and is not what an insertion of one nucleotide does (lines 17494-17496). This is a Scientific Reasoning and Problem Solving question because you must apply the relationship between insertion length and reading-frame integrity to explain why two similar mutations differ so sharply in their effect on protein function.', 'hard', '1C', 'Transmission of Heritable Information from Generation to Generation', 'biology', 2, 150)
  RETURNING id
)
