-- Q4 [Mutations] medium skill2 ans=D
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES ('bio_biochem', 'Genetics and Evolution', 'Mutations', 'A patient with sickle-cell anemia produces a full-length hemoglobin beta chain in which the glutamate normally found at position six is replaced by valine, and this is the only difference from the normal beta-chain sequence. On the basis of this single amino acid change in an otherwise intact chain, the underlying DNA alteration is most consistent with', '[{"label": "A", "text": "a silent change leaving protein unchanged"}, {"label": "B", "text": "a frameshift from a deleted base"}, {"label": "C", "text": "a point mutation creating a stop codon"}, {"label": "D", "text": "a base substitution swapping one amino acid"}]'::jsonb, 'D', 'This is a Biology question that falls under the content category ''Transmission of Heritable Information from Generation to Generation.'' The answer is D because sickle-cell hemoglobin arises from a point mutation, a single-base substitution in which one base is replaced by another, and the textbook states that such point mutations ''can result in the replacement of one amino acid by another, which may alter the function of the protein.'' The textbook specifies that ''In normal hemoglobin, the amino acid at position six is glutamate. In sickle cell hemoglobin glutamate is replaced by valine,'' a ''single amino acid substitution'' produced by ''a single base change (point mutation).'' Because exactly one amino acid changes and the rest of the beta chain is intact and full length, the data point to a base substitution that swaps one amino acid for another, not a shift in reading frame or an early termination. (Choice A) is incorrect because silent mutations are ''not detectable in the final product'' and leave the amino acid unchanged, yet here glutamate is clearly replaced by valine. (Choice B) is incorrect because a frameshift from a deleted base ''results in the alteration of the translational reading frame,'' making the ''resultant protein usually nonfunctional'' with many downstream residues altered, not a single substitution in an otherwise full-length chain. (Choice C) is incorrect because a point mutation that generates a stop codon would ''terminate a protein early,'' producing a truncated chain rather than the full-length beta chain described. (Choice D) is correct: a single-base substitution replaced glutamate with valine, the classic point-mutation mechanism of sickle-cell hemoglobin. This is a Scientific Reasoning and Problem Solving question because you must apply the definitions of point, silent, frameshift, and nonsense mutations to reason from the observed single amino acid change to the underlying DNA alteration.', 'medium', '1C', 'Transmission of Heritable Information from Generation to Generation', 'biology', 2, 105)
  RETURNING id
)
