-- Q5 [Mutations] easy skill1 ans=A
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES ('bio_biochem', 'Genetics and Evolution', 'Mutations', 'A geneticist examines a patient''s karyotype and finds that a segment that normally belongs to chromosome 9 has detached and reattached to chromosome 22, a different, nonhomologous chromosome. This chromosomal mutation is classified as a', '[{"label": "A", "text": "translocation."}, {"label": "B", "text": "inversion."}, {"label": "C", "text": "duplication."}, {"label": "D", "text": "point mutation."}]'::jsonb, 'A', 'This is a Biology question that falls under the content category ''Transmission of Heritable Information from Generation to Generation.'' The answer is A because a translocation occurs when a chromosome segment dissociates and reattaches to a different, nonhomologous chromosome, which is exactly what happens when a segment moves from chromosome 9 to chromosome 22. The textbook states that "A translocation occurs when a chromosome segment dissociates and reattaches to a different, nonhomologous chromosome" and that such rearrangements can be benign or damaging depending on how gene positions shift relative to regulatory sequences. (Choice A) is correct: the defining feature of a translocation is the transfer of a segment to a nonhomologous chromosome, matching the 9-to-22 movement described. (Choice B) is wrong because a chromosome inversion is "the detachment, 180° rotation, and reinsertion of part of a chromosome"; the segment stays on its own chromosome and only changes orientation rather than moving to a different chromosome. (Choice C) is wrong because in a duplication "a chromosomal segment may duplicate," producing an extra copy of genetic material, whereas the patient''s segment was relocated without being copied. (Choice D) is wrong because a point mutation is a mutation that "affect[s] a single base pair," a change at the nucleotide level rather than a relocation of a whole chromosome segment. This is a Knowledge of Scientific Concepts and Principles question because you must recall the definition of a translocation and distinguish it from other chromosomal and point mutations.', 'easy', '1C', 'Transmission of Heritable Information from Generation to Generation', 'biology', 1, 70)
  RETURNING id
)
