-- Q6 [Mutations] medium skill1 ans=B
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES ('bio_biochem', 'Genetics and Evolution', 'Mutations', 'A cytogeneticist analyzing a patient''s karyotype identifies a single chromosome in which a segment has been detached, rotated 180°, and reinserted at its original location, reversing the order of the genes it carries without any net gain or loss of genetic material. This structural rearrangement is best classified as a chromosome:', '[{"label": "A", "text": "reciprocal translocation"}, {"label": "B", "text": "inversion"}, {"label": "C", "text": "segmental deletion"}, {"label": "D", "text": "segmental duplication"}]'::jsonb, 'B', 'This is a Biology question that falls under the content category ''Transmission of Heritable Information from Generation to Generation.'' The answer is B because the textbook defines a chromosome inversion as "the detachment, 180° rotation, and reinsertion of part of a chromosome," which reverses the order of the affected genes within the same chromosome; "unless they disrupt a gene sequence, inversions only change gene orientation" and involve no net gain or loss of genetic material. The described event—reversal of gene order on a single chromosome with no material lost or added—matches this definition exactly. (Choice A) A reciprocal translocation "occurs when a chromosome segment dissociates and reattaches to a different, nonhomologous chromosome," moving the segment to another chromosome rather than flipping it in place. (Choice B) is correct: the segment is excised, rotated 180°, and reinserted into the same chromosome, reversing gene orientation with no net change in genetic content. (Choice C) A segmental deletion is when "a chromosomal segment may...lose itself," removing genetic material, but here no material is lost. (Choice D) A segmental duplication is when a chromosomal segment "may duplicate," adding genetic material, but here no material is gained. This is a Knowledge of Scientific Concepts and Principles question because you must recall the textbook definitions of inversion, translocation, deletion, and duplication and match the described event to the correct category.', 'medium', '1C', 'Transmission of Heritable Information from Generation to Generation', 'biology', 1, 100)
  RETURNING id
)
