-- Q8 [Mutations] easy skill1 ans=D
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES ('bio_biochem', 'Genetics and Evolution', 'Mutations', 'In a laboratory study, a researcher exposes a culture of human skin cells to ultraviolet (UV) light and then sequences their DNA to identify newly arising changes in the nucleotide sequence. The mutations the researcher detects in the UV-exposed cells are best classified as which of the following?', '[{"label": "A", "text": "Silent mutations"}, {"label": "B", "text": "Spontaneous mutations"}, {"label": "C", "text": "Point mutations"}, {"label": "D", "text": "Induced mutations"}]'::jsonb, 'D', 'This is a Biology question that falls under the content category ''Transmission of Heritable Information from Generation to Generation.'' The answer is D because the textbook defines an induced mutation as a "mutation that results from exposure to chemicals or environmental agents," and it specifically lists "UV rays" as an environmental agent that produces this type of mutation. Because the changes in this study arise from deliberate exposure to UV light (an external environmental agent), they are induced rather than arising from natural internal reactions. (Choice A) Silent mutations are point mutations "not expressed" in the protein, usually due to a substitution in the third base of a codon; this describes a possible effect on the protein, not the cause of the mutation, and a UV-induced change may or may not be silent. (Choice B) Spontaneous mutations "take place in the cells as a result of chemical reactions taking place naturally without exposure to any external agent" — the opposite of what occurs here, since UV is an external agent. (Choice C) Point mutations are "those mutations that affect a single base pair"; this categorizes a mutation by its structural scale rather than by its environmental cause, so it does not capture the defining feature of UV exposure. (Choice D) is correct: the mutations result from exposure to UV light, an environmental agent, which is the textbook definition of an induced mutation. This is a Knowledge of Scientific Concepts and Principles question because you must recall the definition of an induced mutation and distinguish it from spontaneous mutations and from terms describing a mutation''s structural scale or protein-level effect.', 'easy', '1C', 'Transmission of Heritable Information from Generation to Generation', 'biology', 1, 75)
  RETURNING id
)
