-- Q9 [Mutations] medium skill2 ans=A
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES ('bio_biochem', 'Genetics and Evolution', 'Mutations', 'Alkaptonuria is a recessively inherited condition in which a mutation disables an enzyme, so the amino acids phenylalanine and tyrosine are not properly metabolized and an intermediate accumulates. A genetic counselor is reviewing the molecular basis of this inborn error of metabolism with a family. Which of the following statements about this condition is/are accurate?

I. Affected individuals are homozygous for the nonfunctional allele.
II. Heterozygous carriers express a milder form of the disorder.
III. The functional enzyme is encoded by the recessive allele.', '[{"label": "A", "text": "I only"}, {"label": "B", "text": "III only"}, {"label": "C", "text": "I and III only"}, {"label": "D", "text": "II and III only"}]'::jsonb, 'A', 'This is a Biology question that falls under the content category ''Transmission of Heritable Information from Generation to Generation.'' The answer is A because only statement I is consistent with the textbook description of alkaptonuria. OpenStax states that alkaptonuria is a recessive genetic disorder in which two amino acids, phenylalanine and tyrosine, are not properly metabolized, that affected individuals have the genotype \(aa\), and that unaffected individuals have the genotype \(AA\) or \(Aa\). Because a nonfunctional allele arises by mutation and the wild-type, functional copy is dominant over the nonfunctional allele, the disorder appears only in individuals who are homozygous recessive for the nonfunctional allele (statement I). (Choice A) is correct: statement I alone matches the source, since affected \(aa\) individuals carry two copies of the nonfunctional, recessive allele. (Choice B) III only is wrong because the recessive allele is the nonfunctional one; the functional enzyme is encoded by the dominant wild-type allele, so III is false. (Choice C) I and III only is wrong because it pairs the true statement I with the reversed statement III. (Choice D) II and III only is wrong because the textbook explains that recessive alleles can be ''carried'' and not expressed by heterozygous ''carriers,'' so heterozygotes are phenotypically unaffected rather than showing a milder form (II is false), and III remains reversed. This is a Scientific Reasoning and Problem Solving question because you must apply the relationship between a recessive nonfunctional allele, genotype, and phenotype to evaluate each statement.', 'medium', '1C', 'Transmission of Heritable Information from Generation to Generation', 'biology', 2, 105)
  RETURNING id
)
