-- Q10 [Hardy-Weinberg Equilibrium] easy skill1 ans=B
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES ('bio_biochem', 'Genetics and Evolution', 'Hardy-Weinberg Equilibrium', 'A large population of beetles is in Hardy-Weinberg equilibrium at a locus that controls shell color, with allele frequencies \(p\) and \(q\) holding steady across generations. The allele frequencies would be expected to begin changing from one generation to the next if which of the following conditions started to occur?', '[{"label": "A", "text": "Beetles continue to mate at random"}, {"label": "B", "text": "Darker beetles survive predation more often"}, {"label": "C", "text": "The population still numbers in the millions"}, {"label": "D", "text": "No beetles enter or leave the population"}]'::jsonb, 'B', 'This is a Biology question that falls under the content category ''Transmission of Heritable Information from Generation to Generation.'' The answer is B because the Hardy-Weinberg principle assumes ''an infinitely large population and conditions with no mutations, migration, emigration, or selective pressure for or against genotype'' (OpenStax Biology 2e, lines 22819-22820); when one of those conditions fails, the population evolves and allele frequencies change. When the five assumptions hold, \(p\) and \(q\) stay constant, so the genetic structure \(p^2 + 2pq + q^2 = 1\) reproduces unchanged each generation. A survival advantage for darker beetles is selective pressure for a genotype: the favored allele is passed on at a higher rate, so its frequency rises while \(q\) falls, and the equilibrium values of \(p\) and \(q\) shift. The textbook notes that ''if the frequencies of alleles or genotypes deviate from the value expected from the Hardy-Weinberg equation, then the population is evolving'' (lines 22869-22870). (Choice A) is incorrect: random mating is one of the required assumptions, so it preserves rather than disrupts equilibrium; nonrandom mating is listed separately as an evolutionary force (lines 22942-22943). (Choice B) is correct: selective pressure for or against a genotype is explicitly excluded by the Hardy-Weinberg assumptions, so it drives \(p\) and \(q\) away from their constant values (lines 22819-22820, 22797-22801). (Choice C) is incorrect: a very large (''infinitely large'') population is exactly the condition the principle requires to avoid genetic drift, so it maintains equilibrium (line 22819). (Choice D) is incorrect: no migration or emigration is one of the stated assumptions, so the absence of movement keeps frequencies stable; it is gene flow, the movement of alleles in and out, that disrupts equilibrium (lines 22820, 23070-23071). This is a Knowledge of Scientific Concepts and Principles question because you must recall the Hardy-Weinberg assumptions and identify which scenario violates them.', 'easy', '1C', 'Transmission of Heritable Information from Generation to Generation', 'biology', 1, 75)
  RETURNING id
)
