  SELECT id, 'A', 'adjacent_fact', NULL FROM q
  UNION ALL
  SELECT id, 'B', 'misconception', NULL FROM q
  UNION ALL
  SELECT id, 'C', 'adjacent_fact', NULL FROM q;

-- Q22 [Genetic Drift & Population Change] medium skill2 ans=C
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES ('bio_biochem', 'Genetics and Evolution', 'Genetic Drift & Population Change', 'Two populations of a lizard species live on neighboring islands and have evolved slightly different allele frequencies at several loci. A storm deposits floating debris that lets a number of lizards drift from one island and breed with residents of the other. As this migration continues across generations, it most directly affects the recipient population''s gene pool by:', '[{"label": "A", "text": "reshaping it to match a few founding migrants"}, {"label": "B", "text": "randomly eliminating alleles by chance sampling"}, {"label": "C", "text": "introducing alleles and reducing between-population differences"}, {"label": "D", "text": "abruptly shrinking variation after a catastrophe"}]'::jsonb, 'C', 'This is a Biology question that falls under the content category ''Transmission of Heritable Information from Generation to Generation.'' The answer is C because gene flow is the flow of alleles in and out of a population due to the migration of individuals or gametes; OpenStax states this "variable flow of individuals in and out of the group not only changes the population''s gene structure, but it can also introduce new genetic variation to populations in different geological locations and habitats" (lines 23071-23078). Because migrants carry alleles from the source island into the recipient island, gene flow adds new variation to the recipient pool while making the two geographically separated groups'' allele frequencies more similar — the textbook notes that ongoing gene flow keeps an allele''s frequency at one end of a range "similar to the allele''s frequency at the other end," whereas blocking that flow lets frequencies "gradually become increasingly different" (lines 22117-22123). (Choice A) describes the founder effect, in which "the genetic structure changes to match that of the new population''s founding fathers and mothers" when a small group starts a new population (lines 23012-23014); here migrants are joining an existing population, not founding a new one. (Choice B) describes genetic drift, "simply the effect of chance," which removes alleles by random sampling rather than by directed migration (lines 22956-22980). (Choice C) is correct: migration of individuals moves alleles into the recipient pool, adding variation and homogenizing allele frequencies between the separated islands (lines 23071-23078, 22117-22123). (Choice D) describes the bottleneck effect, in which a catastrophe such as an earthquake "results in suddenly wiping out a large portion of the gene pool," reducing variation rather than adding it (lines 23000-23003). This is a Scientific Reasoning and Problem Solving question because you must apply the definition of gene flow to predict its specific effect on a recipient population''s alleles and distinguish it from drift, founder, and bottleneck effects.', 'medium', '1C', 'Transmission of Heritable Information from Generation to Generation', 'biology', 2, 105)
  RETURNING id
)
